<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import DefaultLayout from '@/layouts/DefaultLayout.vue';import BaseButton from '@/components/ui/BaseButton.vue';import{useCourseStore}from'@/stores/courses';import{useAuthStore}from'@/stores/auth';import{useApi}from'@/composables/useApi';import type{ApiResponse,Order,Review}from'@/types';
const route=useRoute(),router=useRouter(),courses=useCourseStore(),auth=useAuthStore(),api=useApi(),reviews=ref<Review[]>([]),summary=ref({averageRating:0,totalReviews:0}),rating=ref(5),content=ref(''),actionError=ref(''),working=ref(false)
const course=computed(()=>courses.currentCourse),ownReview=computed(()=>reviews.value.find(r=>r.user.id===auth.user?.id));const money=(n:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(n)
async function loadReviews(){if(!course.value)return;const r=await api.get<ApiResponse<{items:Review[];summary:{averageRating:number;totalReviews:number}}>>(`/courses/${course.value.id}/reviews`);reviews.value=r.data?.items||[];summary.value=r.data?.summary||summary.value;if(ownReview.value){rating.value=ownReview.value.rating;content.value=ownReview.value.content||''}}
async function primaryAction(){if(!auth.isLoggedIn){router.push({path:'/login',query:{redirect:route.fullPath}});return}if(!auth.isStudent){actionError.value='Chỉ tài khoản học viên có thể đăng ký khóa học';return}if(!course.value)return;working.value=true;actionError.value='';try{if(course.value.isFree){await api.post(`/courses/${course.value.id}/enroll`);router.push('/my-courses')}else{const r=await api.post<ApiResponse<Order>>('/orders',{courseIds:[course.value.id]});if(r.data)router.push(`/checkout/${r.data.id}`)}}catch(e){actionError.value=e instanceof Error?e.message:'Không thể thực hiện'}finally{working.value=false}}
async function saveReview(){if(!course.value)return;try{const payload={rating:rating.value,content:content.value.trim()||null};if(ownReview.value)await api.patch(`/reviews/${ownReview.value.id}`,payload);else await api.post(`/courses/${course.value.id}/reviews`,payload);await loadReviews()}catch(e){actionError.value=e instanceof Error?e.message:'Không gửi được đánh giá'}}
async function deleteReview(){if(ownReview.value&&confirm('Xóa đánh giá của bạn?')){await api.del(`/reviews/${ownReview.value.id}`);content.value='';rating.value=5;await loadReviews()}}
onMounted(async()=>{await courses.fetchCourseBySlug(String(route.params.slug));await loadReviews()})
</script>
<template><DefaultLayout><div v-if="courses.loading" class="py-24 text-center">Đang tải...</div><main v-else-if="course"><section class="bg-gradient-to-br from-violet-700 via-purple-600 to-fuchsia-600 text-white"><div class="mx-auto grid max-w-6xl gap-10 px-4 py-14 md:grid-cols-[1fr_360px]"><div><RouterLink to="/courses" class="text-purple-100">← Tất cả khóa học</RouterLink><p class="mt-7 text-sm font-bold uppercase tracking-widest text-amber-300">{{ course.category?.name }}</p><h1 class="mt-3 text-4xl font-black md:text-5xl">{{ course.title }}</h1><p class="mt-5 max-w-3xl text-lg text-purple-50">{{ course.description }}</p><p class="mt-5">Giảng viên: <b>{{ course.instructor?.fullName }}</b> · {{ course.language }}</p></div><aside class="rounded-3xl bg-white p-6 text-slate-900 shadow-2xl"><img v-if="course.thumbnailUrl" :src="course.thumbnailUrl" class="mb-5 aspect-video w-full rounded-2xl object-cover"><p class="text-3xl font-black text-purple-600">{{ course.isFree?'Miễn phí':money(course.price) }}</p><BaseButton class="mt-5 w-full" :loading="working" @click="primaryAction">{{ course.isFree?'Đăng ký học miễn phí':'Mua khóa học' }}</BaseButton><p v-if="actionError" class="mt-3 text-sm text-red-600">{{ actionError }}</p></aside></div></section><section class="mx-auto grid max-w-6xl gap-9 px-4 py-12 md:grid-cols-[1fr_360px]"><div class="space-y-9"><div><h2 class="text-2xl font-extrabold">Giới thiệu</h2><p class="mt-3 whitespace-pre-line text-slate-600 dark:text-slate-300">{{ course.description }}</p></div><div><h2 class="text-2xl font-extrabold">Bạn sẽ học được gì?</h2><p class="mt-3 whitespace-pre-line text-slate-600 dark:text-slate-300">{{ course.learningOutcomes||'Nội dung sẽ được giảng viên cập nhật.' }}</p></div><div><h2 class="text-2xl font-extrabold">Yêu cầu</h2><p class="mt-3 whitespace-pre-line text-slate-600 dark:text-slate-300">{{ course.requirements||'Không có yêu cầu đặc biệt.' }}</p></div></div><div class="rounded-2xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h3 class="font-bold">Thông tin khóa học</h3><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between"><dt>Cấp độ</dt><dd>{{ course.level }}</dd></div><div class="flex justify-between"><dt>Ngôn ngữ</dt><dd>{{ course.language }}</dd></div><div class="flex justify-between"><dt>Trạng thái</dt><dd>{{ course.status }}</dd></div></dl></div></section><section class="mx-auto max-w-6xl px-4 pb-14"><h2 class="text-2xl font-extrabold">Đánh giá khóa học</h2><p class="mt-2 text-xl font-bold text-amber-500">{{ summary.averageRating }} ★ · {{ summary.totalReviews }} đánh giá</p><form v-if="auth.isStudent" class="my-6 rounded-2xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900" @submit.prevent="saveReview"><label class="font-bold">Đánh giá của bạn</label><select v-model.number="rating" class="ml-3 rounded-lg border p-2 dark:bg-slate-800"><option v-for="n in 5" :key="n" :value="n">{{ n }} sao</option></select><textarea v-model="content" class="mt-4 w-full rounded-xl border p-3 dark:bg-slate-800" rows="3" placeholder="Chia sẻ trải nghiệm học tập..."></textarea><div class="mt-3 flex gap-3"><BaseButton type="submit">{{ ownReview?'Cập nhật':'Gửi đánh giá' }}</BaseButton><button v-if="ownReview" type="button" class="text-red-600" @click="deleteReview">Xóa</button></div></form><div class="grid gap-4 md:grid-cols-2"><article v-for="r in reviews" :key="r.id" class="rounded-2xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><div class="flex justify-between"><b>{{ r.user.fullName }}</b><span class="text-amber-500">{{ '★'.repeat(r.rating) }}</span></div><p class="mt-3 text-slate-600 dark:text-slate-300">{{ r.content||'Không có nhận xét.' }}</p></article></div></section></main></DefaultLayout></template>
